import sys

def solve():
    import sys
    import numpy as np

    def dfs(x, y, fig_id):
        if x < 0 or x >= n or y < 0 or y >= m or grid[x][y] != '.':
            return False
        grid[x][y] = str(fig_id)
        stack = [(x, y)]
        size = 0
        while stack:
            cx, cy = stack.pop()
            size += 1
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.':
                    grid[nx][ny] = str(fig_id)
                    stack.append((nx, ny))
        return size in {2, 3, 4, 5}

    n, m = map(int, sys.stdin.readline().split())
    grid = [list(sys.stdin.readline().strip()) for _ in range(n)]

    fig_id = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                fig_id += 1
                if not dfs(i, j, fig_id):
                    print(-1)
                    return

    for row in grid:
        print(''.join(row))

solve()
